import { useState } from "react";

function Counter({ step = 1 }) {
  const [count, setCount] = useState(0);

  function addThree() {
    // updater functions see the latest pending value
    setCount(c => c + step);
    setCount(c => c + step);
    setCount(c => c + step);
    console.log(count); // still the old snapshot
  }

  const parity = count % 2 === 0 ? "even" : "odd"; // derived, not state

  return (
    <div>
      <p>{count} ({parity})</p>
      <button onClick={() => setCount(count + step)}>+{step}</button>
      <button onClick={addThree}>+{3 * step}</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  );
}

export default function App() {
  return <><Counter /><Counter step={10} /></>;
}

import { useState } from "react";

let nextId = 3;

export default function TodoList() {
  const [todos, setTodos] = useState([
    { id: 1, title: "Buy milk", done: false },
    { id: 2, title: "Write tests", done: true },
  ]);
  const [title, setTitle] = useState("");

  const add = () => {
    setTodos([...todos, { id: nextId++, title, done: false }]);
    setTitle("");
  };
  const toggle = id =>
    setTodos(todos.map(t => (t.id === id ? { ...t, done: !t.done } : t)));
  const remove = id => setTodos(todos.filter(t => t.id !== id));

  return (
    <>
      <input value={title} onChange={e => setTitle(e.target.value)} />
      <button onClick={add} disabled={!title}>Add</button>
      <ul>
        {todos.map(t => (
          <li key={t.id}>
            <input type="checkbox" checked={t.done} onChange={() => toggle(t.id)} />
            {t.title} <button onClick={() => remove(t.id)}>x</button>
          </li>
        ))}
      </ul>
    </>
  );
}

concepts.body:
There are two ways to wire an input to React.

A **controlled input** gets its value from state and reports changes through `onChange`:

```jsx
const [name, setName] = useState("");
<input value={name} onChange={e => setName(e.target.value)} />
```

React state is the single source of truth, so you can check the input as the user types (say, that an email contains @), reformat it, disable the submit button, or reset the field by setting state. Checkboxes use `checked` and `e.target.checked`; `<select>` and `<textarea>` use `value` just like inputs.

An **uncontrolled input** keeps its own value inside the page element. You give it an initial `defaultValue` (or `defaultChecked`) and read it when you need it, typically on submit with `FormData`:

```jsx
function handleSubmit(e) {
  e.preventDefault();
  const data = new FormData(e.currentTarget);
  save(data.get("email"));
}
```

Uncontrolled forms are less code and work well when you only care about the values at submit time. In React 19 you can also pass a function to the form's `action` prop; React calls it with the `FormData` and resets the form afterwards. That's the basis of Actions, covered at the Advanced level.

Gotchas:

- Setting `value` without `onChange` makes a read-only input (React warns).
- Don't switch an input between controlled and uncontrolled: `value={undefined}` then `value="x"` triggers a warning. Initialise state to `""`, not `undefined`.
- Every input should have a `name` (for FormData) and a `<label>`, so screen readers can announce what the field is for.

concepts.code:
import { useState } from "react";

export default function SignupForm() {
  const [email, setEmail] = useState("");
  const [agree, setAgree] = useState(false);
  const valid = email.includes("@") && agree;

  function handleSubmit(e) {
    e.preventDefault();                          // no page reload
    const data = new FormData(e.currentTarget);
    console.log(Object.fromEntries(data));       // { email, plan, agree }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Email
        <input name="email" value={email} onChange={e => setEmail(e.target.value)} />
      </label>
      <label>
        Plan
        <select name="plan" defaultValue="free">   {/* uncontrolled */}
          <option value="free">Free</option>
          <option value="pro">Pro</option>
        </select>
      </label>
      <label>
        <input type="checkbox" name="agree" checked={agree}
               onChange={e => setAgree(e.target.checked)} />
        I agree
      </label>
      <button disabled={!valid}>Sign up</button>
    </form>
  );
}

