// Impure: mutates a variable that exists outside the render
let guest = 0;
function BadCup() {
  guest = guest + 1;                    // side effect during render
  return <h2>Tea cup for guest #{guest}</h2>;
}

// Pure: output depends only on props
function Cup({ guest }) {
  return <h2>Tea cup for guest #{guest}</h2>;
}

export default function TeaSet() {
  // Local mutation inside render is fine: the array is created here
  const cups = [];
  for (let i = 1; i <= 3; i++) {
    cups.push(<Cup key={i} guest={i} />);
  }
  return (
    <>
      {cups}
      {/* Under StrictMode this shows #2, #4, #6: the double render exposes the bug */}
      <BadCup /><BadCup /><BadCup />
    </>
  );
}

concepts.body:
Sometimes a component must stay connected to something React doesn't control: a chat server, a browser feature such as window resizing, or a chart drawn by another library. An **Effect** is code that runs **after** React has updated the page, to keep that outside thing in step with your component:

```jsx
useEffect(() => {
  const conn = createConnection(roomId);
  conn.connect();
  return () => conn.disconnect();   // cleanup
}, [roomId]);                        // dependencies
```

Think of it as "keep this outside thing in step with these values", not as "run this when X happens". The **dependency array** (the second argument) lists every value from the component that the Effect reads: props, state, and anything computed from them.

After a render where one of those values changed, React first calls the **cleanup function** you returned, to undo the old setup, then runs the Effect again. With no array, the Effect runs after every render. With `[]`, it runs once when the component **mounts** (first appears on screen) and cleans up when it **unmounts** (is removed).

Never leave a value out of the array just to stop re-runs. A **linter** (a tool that scans code for likely mistakes), `eslint-plugin-react-hooks`, checks the array for you. If an Effect re-runs too often, change the code instead: move an object inside the Effect, or use an updater function. React 19.2 also adds `useEffectEvent` for code inside an Effect that should read the latest values without causing re-runs.

Cleanup must fully undo setup, because Strict Mode deliberately runs setup, cleanup, setup on mount to check it.

**You might not need an Effect.** Effects are for things outside React. Don't use one to:

- compute derived data (`useEffect(() => setFull(first + last))`); compute it during render;
- respond to a user action (send the save request in the submit handler, not in an Effect watching a `submitted` flag);
- reset state when a prop changes; give the component a `key` instead.

Each unnecessary Effect adds an extra render and a moment where the screen shows out-of-date values.

concepts.code:
import { useEffect, useState } from "react";

function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    // a live two-way connection to a chat server
    const socket = new WebSocket(`wss://chat.example.com/rooms/${roomId}`);
    socket.onmessage = e => setMessages(m => [...m, e.data]); // updater: messages needn't be listed
    return () => socket.close();       // runs before the next setup and on unmount
  }, [roomId]);                        // reconnect only when the room changes

  return <ul>{messages.map((m, i) => <li key={i}>{m}</li>)}</ul>;
}

function WindowWidth() {
  const [width, setWidth] = useState(window.innerWidth);
  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return <p>{width}px</p>;
}

export default function App() {
  const [room, setRoom] = useState("general");
  return <><button onClick={() => setRoom("random")}>Switch</button><ChatRoom roomId={room} /><WindowWidth /></>;
}

concepts.body:
A **ref** is a box whose `.current` you can read and write without causing a re-render:

```jsx
const intervalRef = useRef(null);
intervalRef.current = setInterval(tick, 1000);
```

Use refs for values that the rendered output doesn't depend on: timer ids, the previous value of something, an object from another library (say, a map widget). If changing the value should update the screen, it must be state. Don't read or write `ref.current` during rendering (except to fill it in once on the first render); do it in handlers and effects, otherwise rendering becomes impure.

The most common use is reaching **DOM nodes**: the objects for page elements you met in the DOM lesson. Pass a ref object to a built-in element's `ref` attribute and React sets `.current` to the DOM node after it mounts (and back to `null` when it unmounts):

```jsx
const inputRef = useRef(null);
<input ref={inputRef} />
// in a handler: inputRef.current.focus();
```

In React 19, `ref` is an ordinary **prop for function components**: a child can accept `{ ref }` and forward it to an inner element, so the older `forwardRef` helper is no longer needed. You can also pass a function, `ref={node => ...}`, which React calls with the element; it may return a cleanup function.

Use DOM refs for things React doesn't model: focus, scroll position, measuring, media playback, integrating a chart library. Don't use them to change content React manages (adding children, changing text); React will overwrite or crash on it.

A related tool is the **portal**. `createPortal(children, domNode)` from `react-dom` renders children into a different DOM node, like `document.body`, while they stay in the same place in the component tree, so events still bubble up to the React parent. It's how pop-up dialogs, tooltips and notifications appear above everything else, even when a parent element would cut them off.

concepts.code:
import { useRef, useState } from "react";
import { createPortal } from "react-dom";

// React 19: ref is a regular prop, no forwardRef needed
function TextField({ label, ref }) {
  return <label>{label} <input ref={ref} /></label>;
}

export default function Search() {
  const inputRef = useRef(null);
  const renders = useRef(0);          // mutable, never triggers a render
  const [open, setOpen] = useState(false);

  return (
    <>
      <TextField label="Search" ref={inputRef} />
      <button onClick={() => inputRef.current.focus()}>Focus</button>
      <button onClick={() => { renders.current++; setOpen(true); }}>Help</button>
      {open &&
        createPortal(
          <div className="modal">
            <p>Type and press Enter.</p>
            <button onClick={() => setOpen(false)}>Close</button>
          </div>,
          document.body          // rendered here, but still a child in React's tree
        )}
    </>
  );
}

concepts.body:
When several components need the same logic involving state and Effects (tracking whether the user is online, reading the window size, or a value that **debounces**: updates only once the user pauses typing), extract it into a **custom Hook**: a function whose name starts with `use` and that calls other Hooks.

```jsx
function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  useEffect(() => { /* subscribe to online/offline events */ }, []);
  return isOnline;
}
```

Any component can now write `const isOnline = useOnlineStatus();`.

Important properties:

- Custom Hooks share **logic, not state**. Each call gets its own independent state, exactly as if the component had called `useState` and `useEffect` itself.
- They follow the Rules of Hooks: call them at the top level, and only from components or other Hooks. The `use` prefix is how the Hooks linter knows the rules apply.
- They receive fresh arguments on every render, so they can react to changing props: `useChatRoom({ roomId })`.
- A function that doesn't call any Hooks shouldn't be named `useSomething`; make it a plain function.

Good custom Hooks are named after **what they do** for the component (`useOnlineStatus`, `useFormField`, `useMediaQuery`), hiding the effect underneath. Generic wrappers like `useMount` ("run this when the component appears") tend to hide poor Effect use rather than help.

Custom Hooks also make later changes easy: if you replace the code inside, say with a data-loading library, the components calling the Hook don't change.

concepts.code:
import { useEffect, useState } from "react";

// Debounce: wait until value stops changing for `delay` ms
function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}

// localStorage: text the browser keeps for this site across reloads
function useLocalStorage(key, initial) {
  const [value, setValue] = useState(() => {
    const saved = localStorage.getItem(key);
    return saved !== null ? JSON.parse(saved) : initial;
  });
  useEffect(() => localStorage.setItem(key, JSON.stringify(value)), [key, value]);
  return [value, setValue];
}

export default function SearchBox() {
  const [query, setQuery] = useLocalStorage("query", "");
  const debounced = useDebouncedValue(query, 500);
  return (
    <>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      <p>Searching for: {debounced}</p>
    </>
  );
}

import { createContext, use, useContext, useState } from "react";

const ThemeContext = createContext("light");
const UserContext = createContext(null);

function Button({ children }) {
  const theme = useContext(ThemeContext);
  return <button className={`btn btn-${theme}`}>{children}</button>;
