import { memo, useCallback, useMemo, useState } from "react";

const List = memo(function List({ items, onSelect }) {
  console.log("List rendered");
  return <ul>{items.map(i => <li key={i.id} onClick={() => onSelect(i.id)}>{i.name}</li>)}</ul>;
