export default function Products({ products }) {
  const [query, setQuery] = useState("");
  const [theme, setTheme] = useState("light");

  // Recomputed only when products or query change, not when theme changes
  const visible = useMemo(
    () => products.filter(p => p.name.toLowerCase().includes(query.toLowerCase())),
    [products, query]
  );
  // Stable identity so memo(List) can skip re-rendering
  const handleSelect = useCallback(id => console.log("selected", id), []);

  return (
    <div className={theme}>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      <button onClick={() => setTheme(t => (t === "light" ? "dark" : "light"))}>Theme</button>
      <List items={visible} onSelect={handleSelect} />
    </div>
  );
}
