import { Profiler, useState } from "react";

function onRender(id, phase, actualDuration, baseDuration) {
  // phase: "mount" | "update" | "nested-update"
  // actualDuration: ms spent rendering this commit (with memoization)
  // baseDuration: estimated ms to re-render the whole subtree without memoization
  if (actualDuration > 16) {
    console.warn(`${id} ${phase} took ${actualDuration.toFixed(1)}ms (base ${baseDuration.toFixed(1)}ms)`);
  }
}

function SlowList({ n }) {
  const items = Array.from({ length: n }, (_, i) => <li key={i}>Row {i}</li>);
  return <ul>{items}</ul>;
}

export default function App() {
  const [n, setN] = useState(1000);
  return (
    <Profiler id="SlowList" onRender={onRender}>
      <button onClick={() => setN(x => x + 5000)}>More rows</button>
      <SlowList n={n} />
    </Profiler>
  );
}

import { Suspense, lazy, use, useState } from "react";

const Chart = lazy(() => import("./Chart.jsx"));   // downloaded as a separate file

// A simple cache so the promise is stable across renders
const cache = new Map();
function fetchUser(id) {
  if (!cache.has(id)) {
    cache.set(id, fetch(`https://jsonplaceholder.typicode.com/users/${id}`).then(r => r.json()));
  }
  return cache.get(id);
}

function UserName({ id }) {
