import { memo, useDeferredValue, useState, useTransition } from "react";

const SlowList = memo(function SlowList({ text }) {
  const items = [];
  for (let i = 0; i < 300; i++) {
    const start = performance.now();
    while (performance.now() - start < 1) {}     // simulate 1ms of work per row
    items.push(<li key={i}>{text} #{i}</li>);
  }
  return <ul>{items}</ul>;
});

export default function App() {
  const [text, setText] = useState("");
  const deferredText = useDeferredValue(text);
  const [tab, setTab] = useState("about");
  const [isPending, startTransition] = useTransition();

  return (
    <>
      <input value={text} onChange={e => setText(e.target.value)} />  {/* stays responsive */}
      <div style={{ opacity: text !== deferredText ? 0.5 : 1 }}>
        <SlowList text={deferredText} />
      </div>
      <button onClick={() => startTransition(() => setTab("posts"))}>
        Posts {isPending && "(loading...)"}
      </button>
      <p>Tab: {tab}</p>
    </>
  );
}

import { Component, Suspense, use } from "react";

class ErrorBoundary extends Component {
  state = { error: null };

  static getDerivedStateFromError(error) {
    return { error };                     // render fallback next
  }
  componentDidCatch(error, info) {
    console.error("Caught:", error, info.componentStack);   // send to an error-tracking service
  }
  render() {
    if (this.state.error) {
      return (
        <div role="alert">
          <p>Couldn't load this section.</p>
          <button onClick={() => this.setState({ error: null })}>Try again</button>
        </div>
      );
    }
    return this.props.children;
  }
}

const failing = Promise.reject(new Error("503 from API"));
function Comments() {
  const comments = use(failing);          // rejection is thrown to the boundary
  return <ul>{comments.map(c => <li key={c.id}>{c.text}</li>)}</ul>;
}

export default function Post() {
  return (
    <ErrorBoundary>
      <Suspense fallback={<p>Loading comments...</p>}>
        <Comments />
      </Suspense>
    </ErrorBoundary>
  );
}

concepts.body:
An **Action** is an async function run inside a transition. React tracks whether it is still running (pending), and the state updates it makes are applied together when it finishes. You get Actions in several ways.

**Form actions.** Pass a function to `<form action={fn}>` (or `<button formAction={fn}>`). React calls it with the form's `FormData` on submit, without a page reload, and resets uncontrolled fields when it succeeds.

**`useActionState(action, initialState)`** returns `[state, formAction, isPending]`. Your action receives `(previousState, formData)` and returns the next state, typically a result or error message:

```jsx
const [error, submit, isPending] = useActionState(async (prev, formData) => {
  const res = await updateName(formData.get("name"));
  return res.error ?? null;
}, null);
<form action={submit}>...</form>
```

Submissions are queued in order, and the state is the last returned value.

**`useFormStatus()`** (from `react-dom`) lets a component *inside* a form read `{ pending, data, method, action }` of the enclosing form's submission. It's perfect for a reusable `<SubmitButton>` that disables itself, without passing props down. It must be called in a child of the `<form>`, not the component that renders it.

**`useOptimistic(state, updateFn)`** shows a temporary value while an Action runs, like a sent message appearing immediately. This is an **optimistic update**: showing the expected result before the server confirms it. When the Action finishes, the optimistic value is discarded and the real state is shown; if it failed, the UI simply reverts.

You can also start an Action from any handler with `startTransition(async () => {...})`. Check (validate) the input in the action, and return errors as state rather than throwing for expected failures. With a framework, the action can even be a Server Function, code that runs on the server (covered at Expert level), so the same form works before the page's JavaScript has loaded.

