import { useActionState, useOptimistic } from "react";
import { useFormStatus } from "react-dom";

async function saveTodo(text) {
  await new Promise(r => setTimeout(r, 800));
  if (text.length < 3) throw new Error("Too short");
  return { id: crypto.randomUUID(), text };
}

function SubmitButton() {
  const { pending } = useFormStatus();          // reads the parent <form>
  return <button disabled={pending}>{pending ? "Saving..." : "Add"}</button>;
}

export default function Todos() {
  const [state, formAction] = useActionState(async (prev, formData) => {
    const text = formData.get("text");
    addOptimistic(text);
    try {
      return { todos: [...prev.todos, await saveTodo(text)], error: null };
    } catch (e) {
      return { ...prev, error: e.message };
    }
  }, { todos: [], error: null });

  const [optimisticTodos, addOptimistic] = useOptimistic(
    state.todos,
    (todos, text) => [...todos, { id: "pending", text: text + " (saving)" }]
  );

  return (
    <form action={formAction}>
      <input name="text" />
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
      <ul>{optimisticTodos.map(t => <li key={t.id}>{t.text}</li>)}</ul>
    </form>
  );
}

import { useLayoutEffect, useEffect, useState, startTransition } from "react";

// Logs illustrate the render/commit/effects ordering.
function Child({ value }) {
  console.log("render Child", value);           // may run without committing
  useLayoutEffect(() => console.log("layout effect", value)); // commit phase, sync
  useEffect(() => console.log("passive effect", value));      // after paint
  return <p>{value}</p>;
}

export default function App() {
  const [urgent, setUrgent] = useState("");
  const [slow, setSlow] = useState("");

  function onChange(e) {
    setUrgent(e.target.value);                     // sync lane: never interrupted
    startTransition(() => setSlow(e.target.value)); // transition lane: may restart
  }

  return (
    <>
      <input value={urgent} onChange={onChange} />
      <Child value={slow} />
    </>
  );
}
