import { useSyncExternalStore } from "react";

// A tiny store living outside React
function createStore(initial) {
  let state = initial;
  const listeners = new Set();
  return {
    getState: () => state,                      // same object until changed
    setState(update) {
      state = { ...state, ...update(state) };    // new immutable snapshot
      listeners.forEach(l => l());
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

const cartStore = createStore({ count: 0 });

function useCartCount() {
  return useSyncExternalStore(
    cartStore.subscribe,
    () => cartStore.getState().count,           // primitive: stable by Object.is
    () => 0                                     // server snapshot
  );
}

export default function CartBadge() {
  const count = useCartCount();
  return <button onClick={() => cartStore.setState(s => ({ count: s.count + 1 }))}>Cart ({count})</button>;
}

