"use server";
import { z } from "zod";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";
import { revalidatePath } from "next/cache";

const NoteSchema = z.object({ title: z.string().min(1).max(100) });

export async function createNote(prevState, formData) {
  const session = await getSession();
  if (!session) return { error: "Please sign in." };          // authenticate

  const parsed = NoteSchema.safeParse({ title: formData.get("title") });
  if (!parsed.success) return { error: "Title must be 1-100 characters." };  // validate

  await db.notes.create({ ownerId: session.userId, title: parsed.data.title });
  revalidatePath("/notes");                                   // refresh server data
  return { error: null };
}

